    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self):
        """Basic initialization."""
        self.ROBOT_LIBRARY_LISTENER = self
        self._align_logs_dir_with_robot()
        self._align_debuglevel_with_robot()
        core_logging.install_additional_handlers_builder(builder_function=robot_console_redirecting_handler.append_robot_console_handler)
        ute_ue_robot_logging.configure_loggers()
        self.logger = logging.getLogger('ute_ue')
        self._ue_specific_methods, self._ue_specific_methods_names = self._get_ue_specific_methods()
        self._hidden_keywords = self._get_hidden_keywords()
        self._config_applied = False
        self._config_source = self._get_config_source()
        self._python_api = False
        self._keep_reservation = None
        self._compress_all_logs = None
        self._log_paths = None

        self._kw_data = TestData()

        self._fails = []

    def _get_config_source(self):
        return config_source.BackwardCompatibleSource()

    def get_keyword_names(self):
        """
        Returns list of keywords that library provides including device specific ones

        :return: list of keywords
        """
        keyword_names = [method for method in dir(self) if method[0] != '_' and 'ROBOT' not in method and 'logger' not in method]
        [keyword_names.remove(keyword) for keyword in RESTRICTED_KEYWORDS if keyword in keyword_names]
        keyword_names.extend(self._ue_specific_methods_names)
        [keyword_names.remove(keyword) for keyword in RESTRICTED_KEYWORDS_UE_SPECIFIC if keyword in self._ue_specific_methods_names]
        keyword_names.extend(self._hidden_keywords.keys())
        return keyword_names

    def __getattr__(self, name):  # noqa: C901
        if name in self._hidden_keywords.keys():
            return self._hidden_keywords[name]
        elif name in self._ue_specific_methods_names:
            def _proxy_bf(alias, *args, **kwargs):
                ue = self._get_ue(name, alias)
                try:
                    ue_method = ue.__getattribute__(name)
                except AttributeError:
                    ues_that_support_keyword = self._get_ue_types_having_method(name)
                    raise AttributeError(f"'{name}' keyword cannot be run on {ue} (pointed by alias: '{alias}'). "
                                         f"UEs types that support provided keyword: {ues_that_support_keyword}")
                kw_name_words = [word.capitalize() for word in str(ue_method.__name__).split("_")]
                self._kw_data.kw_name = " ".join(kw_name_words)
                return self._execute_ue_method(ue_method, *args, **kwargs)
            return _proxy_bf
        raise AttributeError(f"'ute_ue' object has no attribute '{name}'")

    def _execute_ue_method(self, ue_method, *args, **kwargs):
        tc_start_time = time.time()
        try:
            ret_val = ue_method(*args, **kwargs)
        except Exception as e:
            self._kw_data.kw_duration = time.time() - tc_start_time
            report = self._kw_data.report_use(error=e)
            if len(report) != 0:
                report_text = self._kw_data.format_info(report=report, error=e, error_nr=len(self._fails) + 1)
                self._fails.append(report_text)
            raise e
        else:
            self._kw_data.kw_duration = time.time() - tc_start_time
            self._kw_data.report_use()
        return ret_val

    def _get_ue_specific_methods(self):
        """
        Return dict of ue specific method-names per ue-type and set of all ue specific method-names

        :return: (dict, list)
        """
        ues_specific_methods = {}
        ues_specific_methods_names = set()
        lteue_methods = self._get_public_api(LteUe)
        try:
            e_p_list = import_lib.entry_points(group='UE_TYPES')
        except TypeError:
            e_p_list = list(import_lib.entry_points().get('UE_TYPES', []))
        for e_p in e_p_list:
            try:
                ue_implementation_class = e_p.load()
                ue_specific_methods_names = list(self._get_public_api(ue_implementation_class) - lteue_methods)

                ues_specific_methods[e_p.name] = ue_specific_methods_names
                ues_specific_methods_names.update(ue_specific_methods_names)
            # we intentionally catch all exceptions
            # since we don't want incorrect plugin to break whole abstract lib core
            except Exception:  # pylint: disable=broad-except
                ue_implementation_class_name = e_p.name
                plugin_descr = f"{e_p.dist.name} ver.{e_p.dist.version}"
                why = f"failed {ue_implementation_class_name} class creation"
                err_msg = f"Won't use UE_TYPE '{ue_implementation_class_name}' from {plugin_descr} - {why}"
                self.logger.warning(err_msg, exc_info=True)

        return ues_specific_methods, list(ues_specific_methods_names)

    def _get_hidden_keywords(self):
        """Such keywords are intentionally hidden to not overuse it by testers. They are NOT visible in the ute_ue documentation"""
        hidden_keywords = {}
        hidden_keywords['stop_using_ue'] = self._stop_using_ue
        return hidden_keywords

    @staticmethod
    def _get_public_api(klass):
        return set([func for func in dir(klass) if callable(getattr(klass, func)) and not func.startswith("_")])  # noqa: C403

    def _get_ue_types_having_method(self, provided_method_name):
        return [ue for ue, methods_names in self._ue_specific_methods.items() if provided_method_name in methods_names]

    def require_cell(self, alias, lnbts_id, lcr_id):
        """
        Create abstract cell described by given parameters.

        :param alias: Alias name assigned to the created cell - used as cell reference inside other methods of API.
        :param lnbts_id: Macro eNB identifier
        :param lcr_id: Local cell resource ID
        :return: None
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)

        _ensure_alias_is_unused(alias)
        self._apply_configuration_from_source()

        with append_alias_to_ne_identification(alias, CellIdentification, only4toolspecific_neid=True):
            cell = testenv.TestEnv().require_cell(lnbts_id=lnbts_id, lcr_id=lcr_id)
        aliases_registry()[alias] = cell

    def require_ue(self, ue_alias=None, capabilities=None, starting_cell=None,  # noqa: C901
                   starting_enb=None, starting_phy_cell=None, keep_reservation=True, keep_reservation_timeout=120.0):
        """
        Find UE that fulfils given requirements and store the ue under given alias.

        :param ue_alias: Alias name assigned to the found UE - used as UE reference inside other methods of UE API.
        :param capabilities: UE capabilities requirement
        :param starting_cell: requirement for starting point of requested UE (E-UTRAN cell identifier) or cell alias -
            cannot be provided with starting_enb or starting_phy_cell
        :param starting_enb: requirement for starting eNB of requested UE -
            cannot be provided with starting_cell; must be provided with starting_phy_cell
        :param starting_phy_cell: requirement for starting cell of requested UE (iPHY cell identifier) -
            cannot be provided with starting_cell; must be provided with starting_enb
        :param keep_reservation: If True, UE will be kept reserved until explicitly released
        :param keep_reservation_timeout: Timeout for keeping UE reserved (in seconds)
        :return: UE instance
        :raises: :py:class:`ute_ue.exceptions.UeCharacteristicsIsEmpty`: If both capabilities and starting_cell are None
        :raises: :py:class:`ute_common_abstract_core.exceptions.ConfigurationNotDefined`: If UE configuration cannot be found
        :raises: :py:class:`ute_ue.exceptions.RequiredUeNotFound`: If matching ue is not found
        :raises: :py:class:`ute_common_abstract_core.exceptions.AliasAlreadyAssignedError`: if ue_alias already used for other UE
        """
        if self._python_api:  # Python api does not use ue_alias, it operates on ue instance
            return self.create_ue(ue_alias=ue_alias, capabilities=capabilities)
        elif ue_alias is None:
            raise TypeError('require_ue() missing 1 required positional argument - "ue_alias"')

        scope.notify_scope_owner_changed(owner=self.__class__.__name__)

        _ensure_alias_is_unused(ue_alias)
        self._apply_configuration_from_source()

        ue_capabilities, capabilities_tags = self._split_tag_and_ue_capabilities(capabilities)
        starting_cell = self._restore_if_inside_aliases_registry(alias=starting_cell, value_type=LteCell)

        ue_definition = UeCharacteristics(domain_capabilities=capabilities_tags,
                                          ue_capabilities=ue_capabilities,
                                          starting_cell=StartingCellConverter('Require UE').
                                          get_starting_cell(starting_cell, starting_enb, starting_phy_cell))
        with append_alias_to_ne_identification(ue_alias, UeIdentification, only4toolspecific_neid=True):
            ue = testenv.TestEnv().require_ue(ue_characteristics=ue_definition)
        _fill_ue_id(ue, ue_alias)

        _extend_ue_logger_with_alias_info(ue=ue, alias=ue_alias)
        ue.logger.info(f"Require UE {ue_alias} {ue_definition} has taken from UEs-pool: {ue}")

        if 'UeAutomatic' not in aliases_registry():
            self.create_bearer_alias("UeAutomatic", 0, 1)

        aliases_registry()[ue_alias] = ue
        ue.alias = ue_alias
        ue.reserved = True

        self.__get_rpc_client(ue)
        self.__init_metadata_for_ue(ue)
        self.__turn_keep_reservation_on(ue, keep_reservation, keep_reservation_timeout)
        return ue

    def __get_rpc_client(self, ue):
        """Get 'rpc_client' element for taf.ue.proxy connection for UE."""
        if not getattr(ue, "rpc_client", None):
            ue.rpc_client = getattr(ue, "ue_pc", None)

    def __init_metadata_for_ue(self, ue):
        """Initialize diagnostic data (metadata) related to UE."""
        ue.diagnostic_data = getattr(ue, 'diagnostic_data', {})
        if not ue.diagnostic_data:
            if not ue.rpc_client:
                ue.diagnostic_data = {}
            else:
                ue.diagnostic_data = requests.get(url=f"{ue.rpc_client.remote_url}/about").json()
        self._kw_data.add_diagnostic_data(ue_alias=ue.alias, diag_data=ue.diagnostic_data)
        self._kw_data.add_ue_id_data(ue_alias=ue.alias, ue_id=ue.ue_id)
        self._kw_data.add_rpc_data(ue_alias=ue.alias, rpc_client=ue.rpc_client)
        self._kw_data.logging_bypasses[ue.alias] = not ue.allow_kw_logs

    def __turn_keep_reservation_on(self, ue, keep_reservation, keep_reservation_timeout):
        """Keep UE reserved if requested by 'keep_reservation' mechanism."""
        if keep_reservation and self._keep_reservation:
            self._keep_reservation.await_ue_thread_stopped(ue_alias=ue.alias)
            if self._keep_reservation.start_keep_reservation(ue, timeout=keep_reservation_timeout):
                ue_thread = self._keep_reservation.main_thread.ues[ue.alias]
                scope.current_scope().uses(resource=ue_thread,
                                           resource_releaser=self._keep_reservation.stop_keep_reservation)

    def require_ue_group(self, ue_group_alias, ues_number, capabilities=None, starting_cell=None,
                         starting_enb=None, starting_phy_cell=None):
        """
        Find group of UEs that fulfils given requirements and store them under ue_group_alias.

        :param ue_group_alias: Alias name to assign to the found UE group (group reference inside other methods of UE API)
        :param capabilities: UE capabilities requirement
        :param starting_cell: requirement for starting point of requested UE (E-UTRAN cell identifier) or cell alias -
            cannot be provided with starting_enb or starting_phy_cell
        :param starting_enb: requirement for starting eNB of requested UE -
            cannot be provided with starting_cell; must be provided with starting_phy_cell
        :param starting_phy_cell: requirement for starting cell of requested UE (iPHY cell identifier) -
            cannot be provided with starting_cell; must be provided with starting_enb
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeCharacteristicsIsEmpty`: If both capabilities and starting_cell are None
        :raises: :py:class:`ute_common_abstract_core.exceptions.ConfigurationNotDefined`: If UE configuration cannot be found
        :raises: :py:class:`ute_ue.exceptions.NotEnoughRequiredUes`: If not enough matching ues found
        :raises: :py:class:`ute_common_abstract_core.exceptions.AliasAlreadyAssignedError`: if ue_alias already used for other UE

        +----------------------------------------------------------------------------------+
        |     Example                                                                      |
        +==================================================================================+
        |                                                                                  |
        | ::                                                                               |
        |                                                                                  |
        |   Require UE Group  ue_group_alias=UEs40msCQI  ues_number=10   capabilities=CA   |
        |                                                                                  |
        +----------------------------------------------------------------------------------+
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)

        _ensure_alias_is_unused(ue_group_alias)
        self._apply_configuration_from_source()

        ue_capabilities, capabilities_tags = self._split_tag_and_ue_capabilities(capabilities)
        starting_cell = self._restore_if_inside_aliases_registry(alias=starting_cell, value_type=LteCell)

        ue_definition = UeCharacteristics(domain_capabilities=capabilities_tags,
                                          ue_capabilities=ue_capabilities,
                                          starting_cell=StartingCellConverter('Require UE Group').
                                          get_starting_cell(starting_cell, starting_enb, starting_phy_cell))
        with extend_aliases_registry_with_ues_from_group_and_append_uegroup_alias_to_ne_identification(ue_group_alias):
            ue_group = testenv.TestEnv().require_ue_group(ue_characteristics=ue_definition, ues_number=int(ues_number))
        ue_group.name = ue_group_alias
        _extend_ue_group_logger_with_alias_info(ue_group, ue_group_alias)
        ue_group.logger.info(f"Require UE group {ue_group_alias} {ue_definition} has taken from UEs-pool: {ue_group}")
        if 'UeAutomatic' not in aliases_registry():
            self.create_bearer_alias("UeAutomatic", 0, 1)
        aliases_registry()[ue_group_alias] = ue_group

    def _split_tag_and_ue_capabilities(self, capabilities):
        """
        Capabilities may be given as string, list or dict.
        Extract list/dict value that is an alias pointing to UeCapabilities object.

        If such found, return value stored under that alias and initial list/dict without that alias.
        If not - return initial list/dict as it was.
        If capabilities is not list/dict - try it as if it was 'single element list'.
        """
        if isinstance(capabilities, dict):
            capabilities_tags, ue_capabilities, ue_capabilities_aliases = self._split_dict_of_tag_and_ue_capabilities(capabilities)
        elif isinstance(capabilities, list):
            capabilities_tags, ue_capabilities, ue_capabilities_aliases = self._split_list_of_tag_and_ue_capabilities(capabilities)
        else:  # single string
            capabilities_tags, ue_capabilities, ue_capabilities_aliases = self._get_single_tag_or_ue_capabilities(capabilities)

        if len(ue_capabilities_aliases) > 1:
            err_msg = "Only one alias of UeCapabilities may occur in capabilities parameter of 'Require Ue'"
            err_msg += f", provided {len(ue_capabilities_aliases)} aliases {ue_capabilities_aliases}"
            raise ValueError(err_msg)
        return ue_capabilities, capabilities_tags

    def _split_dict_of_tag_and_ue_capabilities(self, capabilities):
        ue_capabilities = None
        ue_capabilities_aliases = []
        capabilities_tags = {}

        for key, capability_tag in capabilities.items():
            ue_cap = self._restore_if_inside_aliases_registry(alias=capability_tag, value_type=UeCapabilities)
            if isinstance(ue_cap, UeCapabilities):
                ue_capabilities = ue_cap
                ue_capabilities_aliases.append(capability_tag)
            else:
                capabilities_tags[key] = capability_tag

        return capabilities_tags, ue_capabilities, ue_capabilities_aliases

    def _split_list_of_tag_and_ue_capabilities(self, capabilities):
        ue_capabilities = None
        ue_capabilities_aliases = []
        capabilities_tags = []

        for capability_tag in capabilities:
            ue_cap = self._restore_if_inside_aliases_registry(alias=capability_tag, value_type=UeCapabilities)
            if isinstance(ue_cap, UeCapabilities):
                ue_capabilities = ue_cap
                ue_capabilities_aliases.append(capability_tag)
            else:
                capabilities_tags.append(capability_tag)

        return capabilities_tags, ue_capabilities, ue_capabilities_aliases

    def _get_tag_or_ue_capabilities(self, capability_tag):
        """
        Check if capability_tag is alias to UeCapabilities object.

        return
        """
        ue_capabilities = None  # noqa: F841

    def _get_single_tag_or_ue_capabilities(self, capabilities):
        capability_tag = capabilities
        ue_cap = self._restore_if_inside_aliases_registry(alias=capability_tag, value_type=UeCapabilities)
        if isinstance(ue_cap, UeCapabilities):
            capability_tag = None
            ue_capabilities = ue_cap
            ue_capabilities_aliases = [capability_tag]
        else:
            ue_capabilities = None
            ue_capabilities_aliases = []

        return capability_tag, ue_capabilities, ue_capabilities_aliases

    def _restore_if_inside_aliases_registry(self, alias, value_type):
        """
        Check if value is an alias pointing to object of given type

        If so, return value stored under that alias.
        If not - return alias as value
        """
        restored_value = alias
        if not isinstance(alias, list):  # list may not be a key
            if alias in aliases_registry():
                if isinstance(aliases_registry()[alias], value_type):
                    restored_value = aliases_registry()[alias]
        return restored_value

    def create_bearer_alias(self, alias, qci, pdn):
        """
        Creates bearer type that identifies bearer (via qci/pdn pair) and
        stores it inside aliases_registry under provided alias

        :param alias: alias of bearer type
        :param qci: QCI for bearer
        :param pdn: PDN used for bearer
        :return: None
        :raises: :py:class:'ute_ue.exceptions.BearerCreationImpossible'
        :raises: :py:class:`ute_common_abstract_core.exceptions.AliasAlreadyAssignedError`: if alias already used
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        _ensure_alias_is_unused(alias)
        self._apply_configuration_from_source()

        bearer_type = testenv.TestEnv().create_bearer_type(qci=qci, pdn=pdn)
        aliases_registry()[alias] = bearer_type

    def create_ue_capabilities_alias(self, alias, hex=None, description=None):
        """
        Creates UeCapabilities object and stores it inside aliases_registry under provided alias.

        UeCapabilities may be defined either via raw hex value
        or as description of required fields of ueCapabilityInformation.

        Created alias may be used inside 'Require UE' keyword inside 'capabilities' parameter

        +------------------------------------------------------------------------------------------------------------------+
        |   Example                                                                                                        |
        +==================================================================================================================+
        |                                                                                                                  |
        | ::                                                                                                               |
        |                                                                                                                  |
        |   Create UE Capabilities alias  CA_2CC_capab  hex=0xD50000300083140E1F87F0FC3F87E1FC3F0FD787FC700184018080308000 |
        |   Create UE Capabilities alias  CAT5_capab    description='ue-Category eq 4'                                     |
        |   Require UE                    UE_CA_2CC     capabilities=CA_2CC_capab                                          |
        |   Require UE                    UE_CAT5       capabilities=CAT5_capab                                            |
        |                                                                                                                  |
        +------------------------------------------------------------------------------------------------------------------+

        Either hex or description parameter should be provided (not both).

        :param alias: alias of UeCapabilities
        :param hex: ue capabilities encoded as hex string starting from 0x
        :param description: ue capabilities as string describing fields of UeCapabilityInformation message
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.AliasAlreadyAssignedError`: if alias already used
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        _ensure_alias_is_unused(alias)
        self._apply_configuration_from_source()

        ue_capabilities = testenv.TestEnv().create_ue_capabilities(hex=hex, description=description)
        aliases_registry()[alias] = ue_capabilities

    def bearer_should_be_active(self, bearer_alias, ue_alias):
        """
        Fails if bearer is not active.

        :param bearer_alias: alias of bearer type
        :param ue_alias: alias of UE on which we check bearer
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UnknownAlias`: If bearer type or ue alias does not exist
        """
        bearer_type = self._get_bearer_type('Bearer should be active', bearer_alias)
        ue = self._get_ue('Bearer should be active', ue_alias)
        assert ue.bearer_is_active(bearer_type), \
            f"Bearer {bearer_alias} of UE {ue_alias} is not active but expected to be"

    def bearer_should_be_inactive(self, bearer_alias, ue_alias):
        """
        Fails if bearer is not inactive.

        :param bearer_alias: alias of bearer type
        :param ue_alias: alias of UE on which we check bearer
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UnknownAlias`: If bearer type or ue alias does not exist
        """
        bearer_type = self._get_bearer_type('Bearer should be active', bearer_alias)
        ue = self._get_ue('Bearer should be active', ue_alias)
        assert not ue.bearer_is_active(bearer_type), \
            f"Bearer {bearer_alias} of UE {ue_alias} is not active but expected to be"

