        """
        Performs dedicated bearer activation initiated from UE side.

        :param bearer_alias: previously assigned bearer type alias
        :param ue_alias: ue alias on which we want to perform bearer activation
        :param activation_params: params come from LTE standard: TS 36.413
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UnknownAlias`: If bearer alias does not exist
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        bearer_type = self._get_bearer_type('Activate dedicated bearer', bearer_alias)
        ue = self._get_ue('Activate dedicated bearer', ue_alias)

        ue.activate_dedicated_bearer(bearer_type=bearer_type, **activation_params)

        # TODO: should be part of plugin compatibility testing
        # TODO: see test_interface/test_activate_dedicated_bearer_method_with_minimum_params_is_correctly_passed_to_python_layer
        # bearer = ue.bearers[-1]
