    @collect_kw_data
    def activate_dedicated_bearers(self, ue_alias, **bearers):
        """
        Performs dedicated bearers activation initiated from UE side.

        Example::

          activate_dedicated_bearers  ue_1  bearer_qci7=(filter:1 precedence:1)  bearer_qci6=(filter:2 precedence:2)
          activate_dedicated_bearers(ue_1, bearer_qci7='(filter:1 precedence:1)', bearer_qci6='(filter:2 precedence:2)')

        See more: http://doc.ute.nsn-rdnet.net/packages/ute_ue/example/crt/bearers_logic_tests_new.html

        :param ue_alias:
        :param bearers: bearer_alias_1=(parameter_name: parameter_value) bearer_alias_2=(parameter_name: parameter_value)
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UnknownAlias`: If bearer alias does not exist
        """
        ue = self._get_ue('Activate dedicated bearers', ue_alias)

        for bearer_alias, params in bearers.items():
            self._check_bearers_activation_params(params)
            bearers[bearer_alias] = {'params': params.replace(':', '=').replace('(', '').replace(')', '')}
            bearers[bearer_alias]['bearer_type'] = self._get_bearer_type('Activate dedicated bearers', bearer_alias)

        self.logger.debug(f'Bearers to be activate: {bearers}')
        ue.activate_dedicated_bearers(bearers)

    def attach_ue_group(self, ue_group_alias, success_ratio=None, failure_ratio=None, timeout=-1):
        """
        Perform attach on UE group.

        :param ue_group_alias: Alias referring to UE-group.
        :param success_ratio: percent of success attaches, cannot be provided with failure_ratio
        :param failure_ratio: percent of failure attaches, cannot be provided with success_ratio
        :param timeout: Timeout for UE to finish attach procedure (change attach state and connect to cell)
        :return: None

        +-----------------------------------------------------------------------+
        |     Example                                                           |
        +=======================================================================+
        |                                                                       |
        | ::                                                                    |
        |                                                                       |
        |   Attach UE group  ue_group_alias=UEs40msCQI                          |
        |   Attach UE group  ue_group_alias=UEs40msCQI  success_ratio=76.5%     |
        |                                                                       |
        +-----------------------------------------------------------------------+
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        ue_group = self._get_ue_group('Attach Ue Group', ue_group_alias)
        success_ratio, failure_ratio = robot_api._get_success_ratio_and_failure_ratio_in_float_type(success_ratio, failure_ratio)
        if timeout == -1:
            ue_group.attach(success_ratio=success_ratio, failure_ratio=failure_ratio)
        else:
            ue_group.attach(success_ratio=success_ratio, failure_ratio=failure_ratio, timeout=float(timeout))  # TODO: handle robot time formatting

    def detach_ue_group(self, ue_group_alias, timeout=-1):
        """
        Perform detach on UE group.

        :param ue_group_alias: Alias referring to UE group.
        :param timeout: Time for UE to finish detach procedure
        :return: None

        +-------------------------------------------------+
        |     Example                                     |
        +=================================================+
        |                                                 |
        | ::                                              |
        |                                                 |
        |   Detach UE group  ue_group_alias=UEs40msCQI    |
        |                                                 |
        +-------------------------------------------------+
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        ue_group = self._get_ue_group('Detach Ue Group', ue_group_alias)
        if timeout == -1:
            ue_group.detach()
        else:
            ue_group.detach(timeout=float(timeout))  # TODO: handle robot time formatting

    @staticmethod
    def _get_success_ratio_and_failure_ratio_in_float_type(success_ratio, failure_ratio):
        if success_ratio is not None and failure_ratio is not None:
            raise ValueError('success_ratio & failure_ratio cannot be provided both')
        elif success_ratio:
            success_ratio = robot_api._get_checked_ratio_value_without_percent_sign(success_ratio)
        elif failure_ratio:
            failure_ratio = robot_api._get_checked_ratio_value_without_percent_sign(failure_ratio)
        return success_ratio, failure_ratio

    @staticmethod
    def _get_checked_ratio_value_without_percent_sign(ratio_value):
        regex = r'(?P<ratio_actual_value>\d+(.|,)?\d*)%'
        match = re.match(regex, ratio_value)
        if match:
            return float(match.group('ratio_actual_value').replace(',', '.'))
        else:
            raise ValueError('ratio provided in wrong format, examples of expected format: 12%; 45,4%; 23.78%')

    @staticmethod
    def _check_bearers_activation_params(params):
        if not re.search(r'^\(.*\)$', params):  # (___)
            raise Exception(f'Activation parameters have been provided incorrectly: {params}')
        for param in params.replace('(', '').replace(')', '').split(' '):
            if not re.search(r'^(([a-z]|_)+:([a-z]|\d)+)$', param):  # (filter:1|precedence:1|by:ue|remote_port:1)
                raise Exception(f'Activation parameters have been provided incorrectly: {params}')

