    def reestablish_ue(self, ue_alias, cell_alias=None, cause='otherFailure', **kwargs):
        """
        Perform rrc reestablishment on UE.

        :param ue_alias: Alias referring to UE.
        :param cell_alias: Alias referring to cell. Current cell if the parameter is not specified
        :param cause: Reestablishment cause. One of: 'reconfigurationFailure', 'handoverFailure',
            'otherFailure' or 'spare1'. Default value is 'otherFailure'
        :param kwargs: UE specific arguments.
        """
        possible_causes = ['reconfigurationFailure', 'handoverFailure', 'otherFailure', 'spare1']
