    @collect_kw_data
    def change_network_mode(self, ue_alias, network_mode_args, *args, **kwargs):
        """
        Changes network mode of UE. Not all UEs and plugins support this method.
        https://taf-ue-android.docs.taf.ute.nsn-rdnet.net/en/latest/
        https://taf-ue-at.docs.taf.ute.nsn-rdnet.net/en/latest/

        :param ue_alias: Alias referring to UE.
        :param network_mode_args: network mode argument value depending on UE plugin. Check details in plugin.
        :return: None
        """  # noqa: E501
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        ue = self._get_ue("change_network_mode", ue_alias)
        if len(args) > 0:
            ue_class = ue.__class__
            sig = signature(ue_class.change_network_mode)
            method_spec_kwargs = [name for name, param in sig.parameters.items() if param.kind in
                                  (Parameter.KEYWORD_ONLY, Parameter.POSITIONAL_OR_KEYWORD) and name not in
                                  ("self", "network_mode_args")]
            msg_warning = ("Please note that 'change_network_mode' keyword accepts only named arguments for plugin "
                           f"{ue_class.__name__}. Here specific parameters are: {method_spec_kwargs}. These values "
                           f"provided as positional argument values here: {args} may not be used in the test.")
            self.logger.warning(msg_warning)
        ue.change_network_mode(network_mode_args, **kwargs)

    @collect_kw_data
    def start_data_transfer(self, dt_name, ue_alias, direction, duration='forever', throughput="100Kbits/sec",
                            bearer_alias="UeAutomatic", protocol='udp', **kwargs_protocol_details):
        """
        Start data transfer on UE. and Verifies that data transfer is started.

        :param dt_name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param ue_alias: Alias referring to UE.
        :param direction: 'ul', 'dl'
        :param duration:
            Data transfer duration in Robot time string format. e.g.  '1 minutes 42 seconds' or '1min 42s'.
            Default value is forever; you need to call stop_data_transfer()
        :param throughput: desired data transfer throughput in iperf string format. e.g.  '100 MBytes/sec'
            :units:

            - 'bits/sec'
            - 'Kbits/sec'           1 000 bits/sec
            - 'Mbits/sec'       1 000 000 bits/sec
            - 'Gbits/sec'   1 000 000 000 bits/sec
            - 'Bytes/sec'               8 bits/sec
            - 'KBytes/sec'          1 000 Bytes/sec
            - 'MBytes/sec'      1 000 000 Bytes/sec
            - 'GBytes/sec'  1 000 000 000 Bytes/sec

            Note: not applicable to the TCP protocol (iperf 2),
        :param bearer_alias: bearer-name
            "UeAutomatic" is reserved name - it means that UE decides which bearer it will use (depends on load).
            Caution: if you don't provide this parameter then call will use same created once during method compilation.
        :param protocol: 'udp' or 'tcp' or 'icmp' or 'http' or 'ftp'. When 'icmp' protocol is used (for ping) additional
            parameters are required: ping_host_ip, ping_count, allowed_packet_loss.
            When 'http' protocol is used additional parameter is required: url.
        :return: DataTransfer instance
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such ue_alias created before via
            require_ue
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if ue_alias doesn't point to UE object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If starting data transfer failed
        :raises: :py:class:`ute_common_abstract_core.exceptions.AliasAlreadyAssignedError`: if dt_name already used as alias
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        if dt_name in aliases_registry():
            alias_logger = logging.getLogger('al.aliases')
            dt = self._get_dt('Start Data Transfer - ensure overnaming finished dt', dt_name)
            if dt.is_running():
                alias_logger.error(f"AliasAssignedToRunningObjectError({dt_name}, {dt})")
                raise AliasAssignedToRunningObjectError(dt_name, dt)
            scope.current_scope().release_resource(resource=dt)
            alias_logger.debug(f"reusing '{dt_name}' alias from not running data transfer {dt}")
            scope.current_scope().release_resource(resource=[dt_name])
        if not isinstance(dt_name, six.string_types):
            raise TypeError(f"KW 'Start Data Transfer' argument 'dt_name' suppose to be string (it is {dt_name.__class__.__name__})")
        ue = self._get_ue('Start Data Transfer', ue_alias)
        bearer = self._get_bearer_type('Start Data Transfer', bearer_alias)
        dt_definition = DataTransferDefinition(direction=direction, duration=duration, throughput=throughput,
                                               bearer=bearer, protocol=protocol,
                                               protocol_details=kwargs_protocol_details)
        data_transfer = ue.start_data_transfer(name=dt_name, dt_definition=dt_definition)
        self._kw_data.bind_ue_alias(ue_alias=ue_alias, dt_alias=dt_name)
        aliases_registry()[dt_name] = data_transfer
        return data_transfer

    @collect_kw_data
    def stop_data_transfer(self, dt_name):
        """
        Stops ongoing data transfer on UE.

        :param dt_name: Name of Data Transfer that is assigned in Start Data Transfer keyword
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If stopping data transfer failed
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        dt = self._get_dt('Stop Data Transfer', dt_name)
        dt.stop()

    def stop_data_transfers_for_all_ues(self):
        """
        Stops all ongoing data transfers that have been started via ute_ue.

        :return:
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        for alias, item in aliases_registry().items():
            if isinstance(item, LteDataTransfer):
                try:
                    item.stop()
                    self.logger.debug(f'DataTransfer ({item}) pointed by alias {alias} has been stopped')
                except Exception as e:
                    self.logger.debug(f"During stopping DT with alias {alias} exception occured: {e}")

    @collect_kw_data
    def await_data_transfer_finish(self, dt_name):
        """
        Awaits completion of ongoing data transfer on UE.

        :param dt_name: Name of Data Transfer that is assigned in Start Data Transfer keyword
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such ue_alias created before via require_ue
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If stopping data transfer failed
        :raises: :py:class:`ute_ue.exceptions.DataTransferCantWaitForeverException`: If this DT has 'forever' duration
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        data_transfer = self._get_dt('Await Data Transfer Finish', dt_name)
        data_transfer.await_finish()

    @collect_kw_data
    def check_data_transfer_is_alive(self, dt_name):
        """
        Checks if data tranfer is running.

        :param dt_name: data transfer alias
        :return:
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        data_transfer = self._get_dt('Check Data Transfer Is Alive', dt_name)
        data_transfer.check_data_transfer()

