    def _get_omit_end_from_last_throughput_period(self, dt, omit=0, end=0, from_last=0):
        """Calculate `omit` regarding to `from_last` positive value"""
        try:
            from_last = int(from_last)
        except (ValueError, TypeError) as e:
            raise ValueError(f"Parameter 'from_last' cannot be converted to a positive integer, got: {from_last} ({e})")
        if from_last > 0:
            msg_warn = (f"Datatransfer {repr(dt)} does not support 'from_last' parameter. There will be "
                        f"used: omit={omit}, end={end} for calculations of Average Throughput!")
            start = getattr(dt, 'client_start_time', 0.0)
            finish = getattr(dt, 'client_finish_time', 0.0)
            start = 0.0 if start is None else start
            finish = 0.0 if finish is None else finish
            if from_last > 0 and start == finish == 0.0:
                self.logger.warning(msg_warn)
                return omit, end
            duration_limit = dt._dt_definition.duration
            now = time.time()
            stop = finish if finish > now else now
            if stop <= start:
                self.logger.warning(msg_warn)
                return omit, end
            dt_period = duration_limit if int(stop - start) > duration_limit else int(stop - start)
            omit = int(dt_period - from_last)
            self.logger.debug(f"Average Throughput for DT moment: {int(now - start)}s, from_last={from_last}s, "
                              f"omit={omit}")
            return omit, 0
        return omit, end

    @collect_kw_data
    def get_average_throughput(self, dt_name, omit=0, end=0, tput_collection_src="iperf", from_last=0, format=None):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time
        or from 'dt.start()' to 'dt.stop()' if data transfer is already finished
        or with currently available iperf intervals that were already transfered.

        If you have started data traffic with direction=simultaneous_ul_dl then you get dictionary with throughput
        for both directions: {'ul': ul_avr_tput, 'dl': dl_avr_tput}.
        Otherwise, you get just float in Kbits/sec indicating avr_tput for ul or dl (as you have selected at start_data_transfer)
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source of data for counting average througput
        :param from_last: period in the seconds up to moment of `end` which will be taken prior to `start`
        :param format: format of unit of return value (Available 'k' - default kbits, 'm' - mbits, 'g' - gbits)
        :return: value of Average throughput in unit: Kbits/sec
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        data_transfer = self._get_dt('Get Average Throughput', dt_name)
        omit, end = self._get_omit_end_from_last_throughput_period(dt=data_transfer, omit=omit, end=end, from_last=from_last)
        try:
            return data_transfer.get_average_throughput_with_params(omit=omit, end=end, tput_collection_src=tput_collection_src, format=format)
        except TypeError as err:
            if "get_average_throughput() takes exactly" in str(err):
                raise TypeError("Parameters 'omit', 'end', 'tput_collection_src' and 'format' are " \
                                "currently supported only with latest taf.ue libraries")
            else:
                raise

    @collect_kw_data
    def verify_average_throughput_with_deviation(self, dt_name, tput, deviation, omit=0, end=0, tput_collection_src="iperf", from_last=0):
        """
        Verify if average throughput is in desired range: tput-(tput*deviation) <-> tput+(tput*deviation)

        If data transfer direction is 'simultaneous_ul_dl' then you can set different tput expectations
        for each direction. You do it using 'extended' format like: 'ul:19Mbits/sec,dl:75Mbits/sec'.
        If you don't use 'extended' format then check like tput='20Mbits/sec' means expect around 20Mbits/sec on both 'ul' and 'dl'.

        Same applies to deviation

        :param dt_name: name of data transfer to be verified
        :param tput: desired average data transfer throughput in string format. e.g. '30Mbits/sec', 'ul:20Mbits/sec,dl:80Mbits/sec'
        :param deviation: acceptable deviation (expressed in percentages) from desired data transfer throughput. e.g '5%', 'ul:5%,dl:7%'
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source of data for verification
        :param from_last: period in the seconds up to moment of `end` or actual, which will be taken for calculations prior to `start`
        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferVerificationFailure`: if verification fails
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if dt_name doesn't point to DataTransfer object
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        data_transfer = self._get_dt('Verify Average Throughput With Deviation', dt_name)
        omit, end = self._get_omit_end_from_last_throughput_period(dt=data_transfer, omit=omit, end=end, from_last=from_last)
        try:
            data_transfer.verify_average_throughput_with_deviation(tput=tput, deviation=deviation, omit=omit, end=end,
                                                                   tput_collection_src=tput_collection_src)
        except TypeError as err:
            if "verify_average_throughput_with_deviation() takes exactly" in str(err):
                raise TypeError("Parameter 'omit', 'end' and 'tput_collection_src' is currently supported only with latest taf.ue libraries")
            else:
                raise

    # @keyword('Verify ${dt_name} Throughput is between ${tput_min} and ${tput_max}')
    # @keyword('Verify ${dt_name} Throughput is above ${tput_min}')

    @collect_kw_data
    def verify_throughput_with_datagram_loss(self, dt_name, max_allowed_datagram_loss):
        """
        Verify if throughput datagram loss is below max_allowed_datagram_loss

        :param dt_name: name of data transfer to be verified
        :param max_allowed_datagram_loss: max acceptable datagram loss in percentage '5%'
        :return: None
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        data_transfer = self._get_dt('Verify Throughput With Datagram Loss', dt_name)
        data_transfer.verify_throughput_with_datagram_loss(max_allowed_datagram_loss=max_allowed_datagram_loss)

    @collect_kw_data
    def verify_average_throughput(self, dt_name, tput_min, tput_max=None, omit=0, end=0, tput_collection_src="iperf", from_last=0):
        """
        Verify if running throughput is in desired range: tput_min <-> tput_max

        If tput_max=None: Verify if running throughput is above desired threshold: tput_min

        If data transfer direction is 'simultaneous_ul_dl' then you can set different tput_min expectations
        for each direction. You do it using 'extended' format like: 'ul:19Mbits/sec,dl:75Mbits/sec'.
        If you don't use 'extended' format then check like tput_min='20Mbits/sec' means expect at least 20Mbits/sec on both 'ul' and 'dl'.

        Same applies to tput_max

        :param dt_name: name of data transfer to be verified
        :param tput_min: lower threshold in string format. e.g. '10Mbits/sec', 'ul:19Mbits/sec,dl:75Mbits/sec'
        :param tput_max: upper threshold in string format. e.g. '20Mbits/sec', 'ul:49Mbits/sec,dl:95Mbits/sec'
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omited.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source of data for verification
        :param from_last: period in the seconds up to moment of `end` which will be taken for calculations prior to `start`
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.DataTransferVerificationFailure`: if verification fails
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        data_transfer = self._get_dt('Verify Average Throughput', dt_name)
        omit, end = self._get_omit_end_from_last_throughput_period(dt=data_transfer, omit=omit, end=end,
                                                                   from_last=from_last)
        try:
            data_transfer.verify_average_throughput(tput_min=tput_min, tput_max=tput_max, omit=omit, end=end,
                                                    tput_collection_src=tput_collection_src)
        except TypeError as err:
            if "verify_average_throughput() takes exactly" in str(err):
                raise TypeError("Parameter 'omit', 'end' and 'tput_collection_src' is currently supported only with latest taf.ue libraries")
            else:
                raise

