    @collect_kw_data
    def start_voice_call(self, vc_alias, ue_alias, to, duration='forever', timeout_start_call=60, timeout_end_call=60,
                         dialing_timeout=None, with_video=False):
        """
        Starts voice call on UE.

        :param vc_alias: alias name to be assigned to voice call. You can use it later on as a reference to voice call.
        :param ue_alias: Alias referring to UE.
        :param to:  Either ue_alias or user identity of Callee. Recommended formats:

            - MSISDN (ITU-T Recommendation E.164)
            - SIP URI (IETF RFC 3261)
            - Tel URI

        :param duration: Duration in Robot time string format. e.g.  '1 minutes 42 seconds' or '1min 42s'.
            Default value is forever; you need to call stop_voice_call()
        :param timeout_start_call:
        :param timeout_end_call:
        :param dialing_timeout:
        :param with_video: Boolean that determines if start a voice call with video.
        :return: VoiceCall instance
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such ue_alias created before via require_ue
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if ue_alias doesn't point to UE object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If starting voice call failed
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        if vc_alias in aliases_registry():
            alias_logger = logging.getLogger('al.aliases')
            vc = self._get_vc('Start Voice Call - ensure overnaming finished vc', vc_alias)
            if not vc.is_finished():
                alias_logger.error(f"AliasAssignedToRunningObjectError({vc_alias}, {vc})")
                raise AliasAssignedToRunningObjectError(vc_alias, vc)
            alias_logger.debug(f"reusing '{vc_alias}' alias from not running voice call {vc}")
            scope.current_scope().release_resource(resource=[vc_alias])
        if not isinstance(vc_alias, six.string_types):
            raise TypeError(f"KW 'Start Voice Call' argument 'vc_alias' suppose to be string (it is {vc_alias.__class__.__name__})")
        if to in aliases_registry():
            method_name = self._get_function_name_robot_style(self.start_voice_call)
            destination_ue = self._get_ue(method_name, to)
            phone_number = destination_ue.phone_number
        else:
            phone_number = to
        vc_definition = VoiceCallDefinition(phone_number, duration, timeout_start_call, timeout_end_call,
                                            dialing_timeout=dialing_timeout, with_video=self.
                                            _convert_param_to_bool(with_video))
        ue = self._get_ue('Start Voice Call', ue_alias)
        vc = ue.start_voice_call(name=vc_alias, definition=vc_definition)
        self._kw_data.bind_ue_alias(ue_alias=ue_alias, vc_alias=vc_alias)
        aliases_registry()[vc_alias] = vc
        return vc

    @collect_kw_data
    def await_incoming_voice_call(self, vc_alias, ue_alias, action="answer", timeout="10s"):
        """
        Executes selected action on incoming voice call.

        :param vc_alias: alias name to be assigned to voice call. You can use it later on as a reference to voice call.
        :param ue_alias: Alias of Ue that should wait.
        :param action: Action to execute on call arrival. Allowed=answer,drop,answer_with_video
        :param timeout: Time to wait for call arrival (robot timestring)
        :return:
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        ue = self._get_ue("Await Incoming Voice Call", ue_alias)
        # TODO: convert timestring to float seconds here
        #       python layer should work on float seconds
        #       timeout = timestr_to_secs(timeout)
        vc = ue.await_incoming_call(name=vc_alias, timeout=timeout)

        actions = {
            "drop": ute_ue._IncomingVoiceCallAction(vc.drop),
            "answer": ute_ue._IncomingVoiceCallAction(vc.answer),
            "answer_with_video": ute_ue._IncomingVoiceCallAction(vc.answer, True)
        }

        action.lower()

        if action not in actions:
            raise AttributeError(f"Action '{action}' is not supported. Supported actions: {list(actions.keys())}")

        actions[action]()

