    @collect_kw_data
    def start_listening_mbms_sessions(self, ue_alias, *session_names):
        """
        Starts mbms session on UE. and Verifies that mbms session is started

        :param ue_alias: Alias referring to UE.
        :param session_names: service ids to be listening on UE
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such ue_alias created before via require_ue
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if ue_alias doesn't point to UE object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If starting data transfer failed
        :raises: :py:class:`ute_common_abstract_core.exceptions.AliasAlreadyAssignedError`: if dt_name already used as alias
        """
        self._check_session_names(session_names)
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        ue = self._get_ue('Start Listening Mbms Sessions', ue_alias)
        for session_name in session_names:
            ue_mbms_session_alias = self._get_mbms_session_alias(ue_alias, session_name)
            if ue_mbms_session_alias in aliases_registry():
                alias_logger = logging.getLogger('al.aliases')
                existing_session = self._get_mbms_session('Start Listening Mbms Sessions - ensure overnaming finished mbms session',
                                                          ue_alias, session_name)
                if existing_session.is_being_verified():
                    alias_logger.error(f"AliasAssignedToRunningObjectError({ue_mbms_session_alias}, {existing_session})")
                    raise AliasAssignedToRunningObjectError(ue_mbms_session_alias, existing_session)
                scope.current_scope().release_resource(resource=existing_session)
                alias_logger.debug(f"reusing '{ue_mbms_session_alias}' alias from not running Mbms Session {existing_session}")
                scope.current_scope().release_resource(resource=[ue_mbms_session_alias])
            assert isinstance(ue_mbms_session_alias, six.string_types)
            mbms_session = ue.create_mbms_session(service_name=session_name)
            aliases_registry()[ue_mbms_session_alias] = mbms_session
        ue.start_listening_mbms_sessions(session_names=session_names)
        for session_name in session_names:
            mbms_sesssion = self._get_mbms_session('Start Listening Mbms Sessions', ue_alias, session_name)
            mbms_sesssion.start_verifying()

    @collect_kw_data
    def stop_listening_mbms_sessions(self, ue_alias, *session_names):
        """
        Stops ongoing mbms sessions on UE. If name is not given all Mbms Sessions are stopped

        :param ue_alias: Alias referring to UE.
        :param session_names: Names of Mbms Sessions that are assigned in Start Listening Mbms Sessions keyword
        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`: if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If stopping data transfer failed
        """
        self._check_session_names(session_names)
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        for session_name in session_names:
            mbms_sesssion = self._get_mbms_session('Stop Listening Mbms Sessions', ue_alias, session_name)
            mbms_sesssion.stop_verifying()

