    @collect_kw_data
    def validate_ue_info(self, ue_alias, info, expected_value, **kwargs):
        """
        Validates specified UE information.

        :param ue_alias: Alias referring to UE.
        :param info: Info type to validate,
            - available values (Android): CELL_ID, IP, MCC, MNC, LAC, PCI, SIGNAL_STRENGTH, IMEI, IMSI, UE_OS_VER, DEVICE_MODEL,
        :param expected_value: Value that the specified info should have.
        :return: None
        """
        scope.notify_scope_owner_changed(owner=self.__class__.__name__)
        ue = self._get_ue('Get UE Info', ue_alias)
        actual_value = ue.get_ue_info(info)
        # For serving multiple infos check
        if isinstance(info, list | tuple | set) and isinstance(info, type(expected_value)):
            if set(actual_value.values()) == set(expected_value):
                return
        else:
            if str(expected_value) == str(actual_value):
                return
        raise ValueDiffersFromExpected(f"Expected {info} value = {expected_value}, actual {info} value = {actual_value}"
                                       )

