    def _get_function_name_robot_style(self, fnc):
        return ' '.join([s.capitalize() for s in fnc.__name__.split('_')])

    def _convert_param_to_bool(self, param):
        return True if str(param).lower() in ['true', 'yes', 'y', 't'] else False

    def _check_session_names(self, session_names):
        if (len(session_names) < 1) or (len(session_names) > 4):
            raise TypeError("Please provide at least 1, and at most 4 session_names")

    def _apply_configuration_from_source(self):
        if self._config_applied:
            return
        abstract_lib_config = self._config_source.pull()
        # Config is singleton so it is constructed only once in the first call and it exist the whole robot run
        loaded_config = config.Config(abstract_lib_config=abstract_lib_config)
        self._load_moler_config(loaded_config)
        self._config_applied = True
        return config

    def _load_moler_config(self, abstract_libs_config):
        if not abstract_libs_config:
            return
        whole_config = abstract_libs_config.get_config()
        if (not whole_config) or ('MOLER' not in whole_config):
            moler_config = {
                'LOGGER': {
                    'PATH': core_logging.get_logging_path(),
                    'DATE_FORMAT': '%Y-%m-%d %H:%M:%S',
                }
            }
            moler.config.load_config(config=moler_config, config_type='dict')
            return
        moler_config = whole_config['MOLER']
        if 'inline_config' in moler_config:
            config_dict = moler_config['inline_config']
            moler_config = self._align_moler_and_ute_ue_loggers(config_dict)
        elif 'config_file_path' in moler_config:
            moler_config_path = config.Config().resolve_config_abspath(moler_config['config_file_path'])
            if moler_config_path:
                config_dict = moler.config.read_yaml_configfile(moler_config_path)
                moler_config = self._align_moler_and_ute_ue_loggers(config_dict)
        else:
            cfg_logger = logging.getLogger('al.config')
            cfg_logger.error(f"MOLER key may have either 'inline_config' or 'config_file_path'; not {moler_config}")
            return
        moler.config.load_config(config=moler_config, config_type='dict')

    def _align_moler_and_ute_ue_loggers(self, moler_config):
        if 'LOGGER' in moler_config:
            moler_config['LOGGER']['PATH'] = core_logging.get_logging_path()
        else:
            moler_config['LOGGER'] = {'PATH': core_logging.get_logging_path()}
        return moler_config

    def _get_ue(self, calling_method_name, ue_alias):
        """
        Finds ue from ue aliases registry or raises exception
        :param calling_method_name: for better error reporting inside exception
        :param ue_alias: alias of UE to find
        :return: UE object if found
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`: if no such ue_alias created before via require_ue
        """
        alias_logger = logging.getLogger('al.aliases')
        if ue_alias not in aliases_registry():
            alias_type_info = f"UE-alias '{ue_alias}'"
            location_info = f" used inside: '{calling_method_name}  {ue_alias}'"
            how_to_fix_info = f"  Have you called 'Require Ue  {ue_alias}  ... ' before '{calling_method_name}  {ue_alias}'?"
            err_msg = alias_type_info + location_info + "\n" + how_to_fix_info
            alias_logger.error(f"UnknownAlias({err_msg})")
            raise UnknownAlias(err_msg)
        ue = aliases_registry()[ue_alias]
        # aliases registry holds objects of different type, check if alias points to LteUe
        if not isinstance(ue, LteUe):
            location_info = f"called from: '{calling_method_name}  {ue_alias}'"
            why_wrong_info = f"  should be alias of LteUe object but it points to '{ue.__class__.__name__}' object"
            expected_preceding_call = "Require Ue  UE_alias  ..."
            how_to_fix_info = f"  you should use UE_alias given at '{expected_preceding_call}'"
            err_msg = location_info + "\n" + why_wrong_info + "\n" + how_to_fix_info
            alias_logger.error(f"WrongAlias({err_msg})")
            raise WrongAlias(err_msg)
        self._kw_data.set_temp_kw_data(ue_alias=ue_alias, plugin_name=ue.__class__.__name__, access_name=ue.access)
        return ue

    def _is_alias_phone_number(self, ue_alias):
        return True if (ue_alias.startswith('+') or ue_alias[0].isdigit()) and ue_alias[1:].isdigit() else False

